            try:
                return int(value_str)
            except ValueError:
                try:
                    return float(value_str)
                except ValueError:
                    return value_str

    def parse_array(array_str):
        array_str = array_str.strip('[]')
        elements = []
        element = ''
        level = 0
        in_quotes = False
        for char in array_str:
            if char == ',' and not in_quotes and level == 0:
                elements.append(parse_value(element))
                element = ''
            else:
                element += char
                if char == '"':
                    in_quotes = not in_quotes
                elif char == '[':
                    level += 1
                elif char == ']':
                    level -= 1
        elements.append(parse_value(element))
        return elements

    def parse_object(obj_str):
        obj_str = obj_str.strip('{}')
        key_value_pairs = {}
        key = ''
        value = ''
        in_quotes = False
        for char in obj_str:
            if char == ':' and not in_quotes:
                key_value_pairs[key] = parse_value(value)
                key = ''
                value = ''
            elif char == ',' and not in_quotes:
                key_value_pairs[key] = parse_value(value)
                key = ''
                value = ''
            else:
                key += char if key else ''
                value += char
                if char == '"':
                    in_quotes = not in_quotes
        key_value_pairs[key] = parse_value(value)
        return key_value_pairs

