def parse_json(json_str):
    def parse_value(value_str):
        if value_str == 'null':
            return None
        if value_str.startswith('"') and value_str.endswith('"'):
            return value_str[1:-1]
        if value_str.startswith('"') or value_str.startswith("'") or value_str.endswith('"') or value_str.endswith("'"):
            return value_str[1:-1]
        if value_str.isdigit():
            return int(value_str)
        try:
            return float(value_str)
        except ValueError:
            pass
        if value_str.lower() == 'true':
            return True
        if value_str.lower() == 'false':
            return False
        raise ValueError(f"Invalid value: {value_str}")

    def parse_list(lst_str):
        lst_str = lst_str.strip()
        if lst_str == '[]':
            return []
        elements = []
        depth = 0
        current_element = ''
        for char in lst_str:
            if char == '[':
                depth += 1
            elif char == ']':
                depth -= 1
            elif char == ',' and depth == 0:
                elements.append(parse_value(current_element))
                current_element = ''
            else:
                current_element += char
        if current_element:
            elements.append(parse_value(current_element))
        return elements

    def parse_dict(dct_str):
        dct_str = dct_str.strip()
        if dct_str == '{}':
            return {}
        key_value_pairs = {}
        depth = 0
        current_key = ''
        current_value = ''
        in_value = False
        for char in dct_str:
            if char == '{':
                depth += 1
            elif char == '}':
                depth -= 1
            elif char == ':' and depth == 1:
                if current_key in key_value_pairs:
                    raise ValueError(f"Duplicate key: {current_key}")
                key_value_pairs[current_key] = parse_value(current_value)
                current_key = ''
                current_value = ''
                in_value = False
            elif char == ',' and depth == 1:
                if current_key in key_value_pairs:
                    raise ValueError(f"Duplicate key: {current_key}")
                key_value_pairs[current_key] = parse_value(current_value)
                current_key = ''
                current_value = ''
                in_value = False
            elif char == '"' or char == "'":
                if in_value:
                    current_value += char
                else:
                    in_value = True
                    current_key += char
            else:
                if in_value:
                    current_value += char
                else:
                    current_key += char
        if current_key or current_value:
            if current_key in key_value_pairs:
                raise ValueError(f"Duplicate key: {current_key}")
            key_value_pairs[current_key] = parse_value(current_value)
        return key_value_pairs

    # Additional fixes for trailing commas and unquoted keys
    if json_str.startswith('[') and json_str.endswith(']'):
        json_str = json_str.rstrip(',\n\r')
    elif json_str.startswith('{') and json_str.endswith('}'):
        json_str = json_str.rstrip(',\n\r')

    return parse_list(json_str) if json_str.startswith('[') else parse_dict(json_str)

