def parse_json(json_str):
    def parse_value(value_str):
        if value_str.startswith('"') and value_str.endswith('"'):
            return value_str[1:-1].replace('\\"', '"').replace("\\\\", "\\")
        if value_str == "true":
            return True
        if value_str == "false":
            return False
        if value_str == "null":
            return None
        try:
            return int(value_str)
        except ValueError:
            try:
                return float(value_str)
            except ValueError:
                return value_str

    def parse_array(array_str):
        array_str = array_str.strip()[1:-1].strip()
        if not array_str:
            return []
        elements = []
        while array_str:
            element, array_str = parse_value(array_str)
            elements.append(element)
            if array_str.startswith(', '):
                array_str = array_str[2:]
            elif array_str.startswith(' '):
                array_str = array_str[1:]
            else:
                break
        return elements

    def parse_object(obj_str):
        obj_str = obj_str.strip()[1:-1].strip()
        if not obj_str:
            return {}
        pairs = {}
        while obj_str:
            key, obj_str = parse_value(obj_str)
            if not obj_str.startswith(': '):
                raise SyntaxError("Invalid JSON object")
            obj_str = obj_str[2:].lstrip()
            value, obj_str = parse_value(obj_str)
            pairs[key] = value
            if obj_str.startswith(', '):
                obj_str = obj_str[2:].lstrip()
            elif obj_str.startswith(' '):
                obj_str = obj_str[1:].lstrip()
            else:
                break
        return pairs

    def parse(json_str):
        json_str = json_str.strip()
        if json_str.startswith('['):
            return parse_array(json_str)
        elif json_str.startswith('{'):
            return parse_object(json_str)
        else:
            return parse_value(json_str)

    return parse(json_str)

