        if value_str == "true":
            return True
        if value_str == "false":
            return False
        if value_str == "null":
            return None
        try:
            return int(value_str)
        except ValueError:
            try:
                return float(value_str)
            except ValueError:
                return value_str

    def parse_list(json_str):
        json_str = json_str[1:-1]  # Remove the brackets
        elements = []
        while json_str:
            json_str, element = parse_value(json_str)
            elements.append(element)
            if json_str.startswith(','):
                json_str = json_str[1:]
        return elements, json_str

    def parse_dict(json_str):
        json_str = json_str[1:-1]  # Remove the brackets
        elements = {}
        while json_str:
            key, json_str = parse_value(json_str)
            json_str = json_str[1:]  # Skip the colon
            value, json_str = parse_value(json_str)
            elements[key] = value
            if json_str.startswith(','):
                json_str = json_str[1:]
        return elements, json_str

    def parse(json_str):
        if json_str[0] == '[':
            return parse_list(json_str)
        elif json_str[0] == '{':
            return parse_dict(json_str)
        else:
            return parse_value(json_str)

    stack = []
    result = None
    i = 0
    while i < len(json_str):
        if json_str[i] == '"':
            j = i + 1
            while j < len(json_str) and json_str[j] != '"':
                j += 1
            if j == len(json_str):
                raise SyntaxError("Unterminated string")
            result, json_str = parse_value(json_str[i:j+1]), json_str[j+1:]
            i = j
        elif json_str[i] in '[]{}':
            if not stack:
                if json_str[i] == '[':
                    stack.append('[')
                elif json_str[i] == ']':
                    raise SyntaxError("Unexpected ']'")
                elif json_str[i] == '{':
                    stack.append('{')
                elif json_str[i] == '}':
                    raise SyntaxError("Unexpected '}'")
            else:
                if json_str[i] == ']':
                    result, json_str = parse_list(json_str)
                    stack.pop()
                elif json_str[i] == '}':
                    result, json_str = parse_dict(json_str)
                    stack.pop()
                elif json_str[i] == '[':
                    stack.append('[')
                elif json_str[i] == '{':
                    stack.append('{')
        elif json_str[i] in ',:':
            if not stack:
                raise SyntaxError("Unexpected ',' or ':'")
            else:
                if json_str[i] == ',':
                    json_str = json_str[1:]
                elif json_str[i] == ':':
                    json_str = json_str[1:]
        else:
            j = i + 1
            while j < len(json_str) and json_str[j] not in '[]{}':
                j += 1
            result, json_str = parse_value(json_str[i:j]), json_str[j:]
            i = j
        if not stack:
            break

    if stack:
        raise SyntaxError("Unmatched brackets")

